package xyz.kd5ujc.scarab.crypto.witness

import cats.syntax.all.*
import java.nio.file.{Files, Path}
import java.nio.charset.StandardCharsets.UTF_8
import scala.util.Random
import xyz.kd5ujc.scarab.codec.Bytes

/** Byron verdicts against the released reference libraries (`fixtures/witness-byron`): every row of
  * the generated Byron corpus and of the strict witness corpus, as `verifySignatureRaw` and
  * `verifyRedeemSigRaw` of cardano-crypto-wrapper 1.7.0.0 over crypton 1.0.6 decided it
  * (`scripts/oracle/byron-donna`). No verdict here is written by hand.
  */
class ByronEd25519ReferenceSuite extends munit.FunSuite:
  import ByronEd25519ReferenceSuite.*
  import WitnessGoldenCorpus.{checked, inputs, Input}

  private def pinned(file: String, sha256: String): String =
    checked(file, Files.readAllBytes(Path.of(file)), sha256).fold(e => fail(e.toString), identity)

  private def corpus(
      inputFile: String,
      inputPin: String,
      referenceFile: String,
      referencePin: String
  ): Vector[(Input, Reference)] =
    val in = inputs(pinned(inputFile, inputPin)).fold(e => fail(e.toString), identity)
    val reference =
      references(pinned(referenceFile, referencePin)).fold(e => fail(e.toString), identity)
    assertEquals(reference.map(_.id), in.map(_.id), referenceFile)
    in.zip(reference)

  private val generated = corpus(
    "fixtures/witness-byron/generated.tsv",
    "1e1e71a2b4c70eef4dbfd23cd548310528dbc42ea56cee311a8145651e2980a4",
    "fixtures/witness-byron/reference-generated.tsv",
    "6431807f6321fae5d86a4590623e6adf1a24bed3ca15899bc4bfb5e8f81837b6"
  )
  private val strictCorpus = corpus(
    "fixtures/witness/vectors.tsv",
    "f79f0a87efbd99ebe159c18211497f6b0d282e7946f1839216dc31bbf99ef918",
    "fixtures/witness-byron/reference-witness-vectors.tsv",
    "3a44a7e45986e5b7e22e60f02c3ceef010941b338ce1395be2d3033653404048"
  )

  private def byron(input: Input) = ByronEd25519.verify(input.key, input.signature, input.message)
  private def strict(input: Input) = StrictEd25519.verify(input.key, input.signature, input.message)

  private def expected(input: Input, verdict: Verdict) = verdict match
    case Verdict.Accept => Right(VerificationResult.SignatureVerified)
    case Verdict.Reject => Right(VerificationResult.SignatureRejected)
    case Verdict.Size =>
      if input.key.size != 32 then Left(WitnessInputError.MalformedPublicKeyLength(input.key.size))
      else Left(WitnessInputError.MalformedSignatureLength(input.signature.size))

  private def accepted(result: Either[?, VerificationResult]) =
    result == Right(VerificationResult.SignatureVerified)

  test("the extended-key and redeem reference paths agree on every row") {
    (generated ++ strictCorpus).foreach((input, r) => assertEquals(r.vkey, r.redeem, input.id))
  }

  test("every generated row has the reference verdict") {
    assertEquals(generated.size, 569)
    generated.foreach((input, r) => assertEquals(byron(input), expected(input, r.vkey), input.id))
  }

  test("every row of the strict witness corpus has the reference's Byron verdict") {
    assertEquals(strictCorpus.size, 2219)
    strictCorpus.foreach((input, r) =>
      assertEquals(byron(input), expected(input, r.vkey), input.id)
    )
  }

  test(
    "each of the three classes holds signatures the reference accepts and the strict rule refuses"
  ) {
    def differing(prefixes: String*) =
      generated.count((input, r) =>
        prefixes.exists(input.id.startsWith) && r.vkey == Verdict.Accept && !accepted(strict(input))
      )
    // non-canonical S (S + L; S + 2L and beyond set bit 253 and are refused by both)
    assertEquals(differing("s-plus-1L-"), 5)
    // small-order A or R
    assert(differing("a-order", "ar-small-", "r-identity-", "r-small-mixed-key-") >= 60)
    // non-canonical A: y >= p, or x = 0 with the sign bit set
    assert(differing("a-y-p-plus-", "a-x0-sign-") >= 10)
    // and in the strict corpus, the 1024 sodium S + L rows
    assertEquals(
      strictCorpus.count((input, r) => r.vkey == Verdict.Accept && !accepted(strict(input))),
      1024 + 5 + 2
    )
  }

  test("the strict rule accepts nothing the Byron rule refuses") {
    (generated ++ strictCorpus).foreach { (input, _) =>
      if accepted(strict(input)) then assert(accepted(byron(input)), input.id)
    }
    // and over mutations of valid signatures: S + kL, flipped bits, other keys
    val random = new Random(392)
    val valid = generated.collect { case (input, r) if r.vkey == Verdict.Accept => input }
    (1 to 2000).foreach { _ =>
      val input = valid(random.nextInt(valid.size))
      val signature = input.signature.toArray
      random.nextInt(3) match
        case 0 =>
          val i = random.nextInt(64)
          signature(i) = (signature(i) ^ (1 << random.nextInt(8))).toByte
        case 1 =>
          val s = BigInt(1, signature.slice(32, 64).reverse) + L * random.nextInt(3)
          le(s).copyToArray(signature, 32)
        case _ => ()
      val mutated = Bytes.fromArray(signature)
      if accepted(StrictEd25519.verify(input.key, mutated, input.message)) then
        assert(accepted(ByronEd25519.verify(input.key, mutated, input.message)), input.id)
    }
  }

  test("a changed reference verdict fails its digest pin") {
    val file = "fixtures/witness-byron/reference-generated.tsv"
    val text = new String(Files.readAllBytes(Path.of(file)), UTF_8)
    assertEquals(
      checked(
        file,
        text.replaceFirst("\taccept\t", "\treject\t").getBytes(UTF_8),
        "6431807f6321fae5d86a4590623e6adf1a24bed3ca15899bc4bfb5e8f81837b6"
      ),
      Left(WitnessGoldenCorpus.Error.DigestMismatch(file))
    )
  }

  test("unknown verdict words and missing columns are malformed rows") {
    assertEquals(references("a\taccept\tmaybe\n"), Left(ReferenceError.MalformedRow(1)))
    assertEquals(references("a\taccept\n"), Left(ReferenceError.MalformedRow(1)))
  }

object ByronEd25519ReferenceSuite:
  private val L = (BigInt(1) << 252) + BigInt("27742317777372353535851937790883648493")

  private def le(value: BigInt): Array[Byte] =
    Array.tabulate(32)(i => ((value >> (8 * i)) & 255).toByte)

  /** A reference verdict: accepted, refused, or not given to the API (a key or signature of the
    * wrong length).
    */
  enum Verdict:
    case Accept, Reject, Size

  object Verdict:
    def parse(word: String): Option[Verdict] = word match
      case "accept" => Some(Accept)
      case "reject" => Some(Reject)
      case "size"   => Some(Size)
      case _        => None

  final case class Reference(id: String, vkey: Verdict, redeem: Verdict)

  enum ReferenceError:
    case MalformedRow(row: Int)

  def references(text: String): Either[ReferenceError, Vector[Reference]] =
    text.linesIterator.toVector.zipWithIndex.traverse { (line, index) =>
      line.split("\t", -1).toVector match
        case Vector(id, vkey, redeem) if id.nonEmpty =>
          (Verdict.parse(vkey), Verdict.parse(redeem))
            .mapN(Reference(id, _, _))
            .toRight(ReferenceError.MalformedRow(index + 1))
        case _ => Left(ReferenceError.MalformedRow(index + 1))
    }
